"""Batched company identity through the security-master front door.

There is one resolver: :func:`dark.security_master.resolve`. This module does
not reimplement its tiers. It hands ``resolve`` a connection that answers the
front door's own ``SELECT`` statements from an in-memory snapshot of
``research.companies``, so:

* the snapshot is loaded by **one** query (:data:`SNAPSHOT_SQL`) or from a file,
* each unique reference is resolved once, with O(1) index lookups,
* tier order, CIK padding, short-ticker bar and canonical walk are exactly
  the front door's.

Policy on top of the front door: an ``alias`` win (Tier-2 name match) is a
*candidate*, never an accepted identity. Only Tier-1 keys and tickers resolve.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path

from dark.security_master import Reference, resolve
from dark.security_master.lookup import _ADR_SQL, _BY_ID_SQL, TIER_SQL

from dark.exclusions_feed.inputs import parse_tsv, sha256_hex

#: Columns of the snapshot, in order. ``aliases`` is ``;``-joined.
SNAPSHOT_COLUMNS = (
    "id",
    "ticker",
    "primary_ticker",
    "cik",
    "lei",
    "figi",
    "isin",
    "security_type",
    "canonical_company_id",
    "name",
    "aliases",
)

#: The single read-only query that produces a snapshot from a live database.
SNAPSHOT_SQL = (
    "SELECT id, ticker, primary_ticker, cik, lei, figi, isin, security_type, "
    "canonical_company_id, name, array_to_string(aliases, ';') AS aliases "
    "FROM research.companies ORDER BY id"
)

RESOLVED = "resolved"
NAME_CANDIDATE = "name_candidate"
UNRESOLVED = "unresolved"
NO_SNAPSHOT = "no_snapshot"

_EXACT_TIERS = frozenset({"cik", "lei", "figi", "isin", "ticker"})


class _SnapshotCursor:
    """Answers exactly the front door's statements; anything else is an error."""

    def __init__(self, snap: CompanySnapshot) -> None:
        self._snap = snap
        self._rows: list[dict] = []

    def execute(self, sql: str, params: dict | None = None) -> None:
        p = params or {}
        s = self._snap
        if sql == _BY_ID_SQL:
            row = s.by_id.get(int(p["v"]))
            self._rows = [row] if row else []
        elif sql == _ADR_SQL:
            self._rows = [{"security_class": "adr"}] if int(p["v"]) in s.adr_ids else []
        elif sql == TIER_SQL["cik"]:
            self._rows = s.by["cik"].get(p["v"], []) + [
                r for r in s.by["cik"].get(p["alt"], []) if p["alt"] != p["v"]
            ]
        elif sql == TIER_SQL["ticker"]:
            self._rows = s.by["ticker"].get(p["v"], [])
        elif sql == TIER_SQL["alias"]:
            self._rows = s.by["alias"].get(p["v"].lower(), [])
        else:
            tier = next((t for t in ("lei", "figi", "isin") if sql == TIER_SQL[t]), None)
            if tier is None:
                raise AssertionError(f"snapshot cannot answer: {sql[:80]}")
            self._rows = s.by[tier].get(p["v"], [])

    def fetchall(self) -> list[dict]:
        return list(self._rows)

    def close(self) -> None:
        self._rows = []


