                a.lower() for a in row.get("aliases_list", ())
            }
            for n in names - {""}:
                self.by["alias"][n].append(row)

    def cursor(self) -> _SnapshotCursor:
        return _SnapshotCursor(self)

    @classmethod
    def from_tsv(cls, path: Path) -> CompanySnapshot:
        data = path.read_bytes()
        _, parsed = parse_tsv(data)
        rows = []
        for r, _sha in parsed:
            canon = r.get("canonical_company_id") or ""
            rows.append(
                {
                    **{c: (r.get(c) or None) for c in SNAPSHOT_COLUMNS},
                    "id": int(r["id"]),
                    "canonical_company_id": int(canon) if canon else None,
                    "aliases_list": tuple(a for a in (r.get("aliases") or "").split(";") if a),
                }
            )
        return cls(rows=rows, digest=sha256_hex(data))


