class Identity:
    """Resolution of one reference, with the policy status applied."""

    status: str
    tier: str
    company_id: int | None
    keys: dict[str, str]
    warnings: tuple[str, ...]

    def company_key(self, fallback_name: str) -> str:
        if self.status == RESOLVED and self.company_id is not None:
            return f"company_id:{self.company_id}"
        return f"name:{fallback_name}"


def resolve_many(
    refs: list[Reference], snapshot: CompanySnapshot | None
) -> dict[Reference, Identity]:
    """Resolve each *unique* reference once. Sorted iteration keeps it stable."""
    out: dict[Reference, Identity] = {}
    for ref in sorted(set(refs), key=repr):
        if snapshot is None:
            out[ref] = Identity(NO_SNAPSHOT, "unresolved", None, {}, ())
            continue
        res = resolve(snapshot, ref)
        if res.company_id is None:
            out[ref] = Identity(UNRESOLVED, res.tier, None, {}, res.warnings)
            continue
        row = snapshot.by_id[res.company_id]
        keys = {k: str(row[k]) for k in ("cik", "lei", "figi", "isin", "ticker") if row.get(k)}
        status = RESOLVED if res.tier in _EXACT_TIERS else NAME_CANDIDATE
        out[ref] = Identity(status, res.tier, res.company_id, keys, res.warnings)
    return out

